    # It uses a dictionary to store the cache entries, where the keys are the function arguments, and the values are the corresponding function return values.
    # If the cache dictionary exceeds the specified 'maxsize', the least recently used entries are discarded to make room for new entries.
    def wrapper(func):
        cache = {}
        calls = {}
        def decorated_function(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key not in calls:
                calls[key] = len(calls)
                cache[key] = func(*args, **kwargs)
            else:
                # Update the MRU list by moving the current entry to the end.
                index = calls[key]
                del calls[key]
                calls[key] = index
            return cache[key]
        return decorated_function
    return wrapper

def mru_cache(maxsize=128, typed=False):
    """ Decorator to wrap a function with a memoizing callable that saves up to
    maxsize results based on a Most Recently Used (MRU) algorithm.

        Parameters:
            maxsize (int): The maximum number of results to store in the cache.
            typed (bool): Whether the cache should be specific to a particular
        class or not.
    """
    cache = OrderedDict()

    def decorate(func):
        nonlocal cache

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            if key in cache:
                res = cache.pop(key)
            else:
                res = func(*args, **kwargs)
            cache[key] = res
            if maxsize == 0:
                cache.popitem(last=False)
            elif len(cache) > maxsize:
                cache.popitem(last=False)
            return res
        return wrapper
    return decorate

