    def decorate(fn):
        def wrapper(self, *args, **kwargs):
            key = (args, tuple(kwargs))
            with self.lock:
                if key not in self.cache:
                    self.cache[key] = fn(self, *args, **kwargs)
                self.counts[key] += 1
                self.queue.append(key)
                while len(self.queue) > maxsize:
                    self.queue.pop(0)
                    if self.counts[self.queue[0]] == 1:
                        del self.counts[self.queue[0]]
                        del self.cache[self.queue[0]]
                return self.cache[key]
        wrapper.cache = {}
        wrapper.counts = {}
        wrapper.lock = Lock()
        wrapper.queue = collections.deque()
        wrapper.typed = typed
        return wrapper
    return decorate

