def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent

    Parameters:
        classes (list[type]): A list of base classes

    Returns:
        list[type]: The ordered minimum equivalent of the input classes
    """

    result = []
    for cls in classes:
        if cls not in result:
            result.append(cls)
            for base in cls.__bases__:
                if base not in result:
                    result.extend(minimalBases([base]))

    return result

