def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent

    Arguments:
        classes (list): A list of base classes

    Returns:
        list: The minimal set of base classes
    """

    # Create a dictionary to map each class to a set of its base classes
    baseClasses = {}
    for cls in classes:
        baseClasses[cls] = set(cls.__bases__)

    # Find the lowest common ancestor of each class
    lowestCommonAncestors = {}
    for cls in classes:
        lowestCommonAncestors[cls] = min(baseClasses[cls], key=baseClasses[cls].__contains__)

    # Create a dictionary to map each class to a set of its base classes
    minimalBases = {}
    for cls in classes:
        minimalBases[cls] = set()
        currentClass = cls
        while currentClass != lowestCommonAncestors[currentClass]:
            minimalBases[cls].add(currentClass)
            currentClass = lowestCommonAncestors[currentClass]

        minimalBases[cls].add(lowestCommonAncestors[cls])

    return minimalBases

