    Args:
        manifest_files (List[str]): List of manifest files
        digests_used (Set[str]): Set of digests used

    Raises:
        MissingDigestError: If a digest is in the manifest but not used
        UnusedDigestError: If a digest is used but not in the manifest
    """
    manifest_digests = set()
    used_digests = set()
    for file in manifest_files:
        with open(file) as f:
            lines = f.readlines()
            for line in lines:
                if line.startswith("?digest="):
                    manifest_digests.add(line.split("?digest=")[1].strip())
    for digest in manifest_digests:
        if digest not in digests_used:
            raise MissingDigestError(f"Digest {digest} is in the manifest but not used")
    for digest in digests_used:
        if digest not in manifest_digests:
            raise UnusedDigestError(f"Digest {digest} is used but not in the manifest")

