def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an instance of InventoryValidator")

    if self.date > prior.date:
        raise ValueError("prior inventory must have a date older than self")

    if self.inv_number < prior.inv_number:
        raise ValueError("prior inventory must have a higher inv_number than self")

    if self.items < prior.items:
        raise ValueError("prior inventory must have more items than self")

    if self.errors != prior.errors:
        for error in prior.errors:
            if error not in self.errors:
                raise ValueError("prior inventory error missing from self")
            else:
                error_idx = self.errors.index(error)
                if prior.errors[error_idx] != error:
                    raise ValueError("prior inventory error out of order")

    if self.warnings:
        for warning in self.warnings:
            if warning not in prior.warnings:
                raise ValueError("self warning missing from prior inventory")
            else:
                warning_idx = prior.warnings.index(warning)
                if self.warnings[warning_idx] != warning:
                    raise ValueError("self warning out of order")

