    # Check if the fixity block is present and is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dict")

    # Check the fixity block structure
    for key in fixity.keys():
        # Check if the key is a string
        if not isinstance(key, str):
            raise ValueError("Fixity key is not a string")
        # Check if the value is a list of strings
        if not isinstance(fixity[key], list):
            raise ValueError("Fixity value is not a list of strings")
        # Check if all the list items are strings
        for item in fixity[key]:
            if not isinstance(item, str):
                raise ValueError("Fixity list item is not a string")

    # Check if all the files in the manifest are referenced in the fixity block
    for file in manifest_files:
        if file not in fixity.values():
            raise ValueError("Fixity block does not reference file " + file)

