    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check the format of `fixity`:
    if not isinstance(fixity, dict) or not all(k in fixity for k in {'checksum', 'hasChecksum', 'lastModified'}):
        raise ValueError("Invalid fixity block: ", fixity)
    if not isinstance(fixity['checksum'], str) or not all(k in fixity for k in {'checksum'}):
        raise ValueError("Invalid fixity block: ", fixity)
    if not isinstance(fixity['hasChecksum'], (bool, int)):
        raise ValueError("Invalid fixity block: ", fixity)
    if not isinstance(fixity['lastModified'], (str,datetime.datetime)):
        raise ValueError("Invalid fixity block: ", fixity)

    # Check if files are referenced in the manifest:
    referenced_files = set(fixity['files'])
    for f in manifest_files:
        if f['path'] in referenced_files:
            referenced_files.remove(f['path'])
        for f in manifest_files:
            if 'children' in f:
                found_in_children = False
                for f in f['children']:
                    if f['path'] in referenced_files:
                        found_in_children = True
                        referenced_files.remove(f['path'])
                if not found_in_children:
                    break
        if not found_in_children:
            raise ValueError("File not found in manifest: " + f['path'])
    if referenced_files:
        raise ValueError("Files not found in manifest: " + str(referenced_files))

