    arguments, a list of remaining arguments not claimed by any subparser)."""

    # Create an ArgumentParser. This will handle any common arguments.
    parser = argparse.ArgumentParser()

    subparser_dictionaries = {}
    for subparser, subparser_parser in subparsers.items():
        # Add the subparser's common arguments to the ArgumentParser.
        for action in subparser_parser._actions:
