def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    args_map = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            # First, pass all arguments to any manually defined argument groups. If any group
            # successfully processes this argument, we're done with it.
            for group in subparser._action_groups:
                for action in group._group_actions:
                    if action.dest == arg:
                        args_map.setdefault(subparser_name, argparse.Namespace())
                        args_map[subparser_name][action.dest] = action.const
                        break

            # Next, pass all arguments to any manually defined arguments. If any argument
            # successfully processes this argument, we're done with it.
            for action in subparser._actions:
                if action.dest == arg:
                    args_map.setdefault(subparser_name, argparse.Namespace())
                    args_map[subparser_name][action.dest] = action.const
                    break

            # If none of the manually defined argument groups or arguments managed to process
            # this argument, it remains unclaimed and will be collected as a remaining argument.
            if arg not in args_map[subparser_name]:
                remaining_args.append(arg)

    return args_map, remaining_args

