def size_to_bytes(size: str) -> int:
    size_unit_suffixes = {'K': 1000, 'M': 1000000, 'G': 1000000000}
    size_prefixes = {'': 1, 'k': 1000, 'm': 1000000, 'g': 1000000000}
    size = size.lower()
    try:
        if size[-1].isdigit():
            mult = int(size[-1])
            if mult not in size_prefixes:
                raise ValueError("invalid unit suffix")
            size = size[:-1]
        else:
            mult = 1
        prefix = size_prefixes[size[-1]]
        if size_unit_suffixes.get(size[-1]):
            prefix = prefix * size_unit_suffixes[size[-1]]
        value = float(size[:-1]) if size[:-1].isdigit() else size[:-1]
        return prefix * mult * value
    except (ValueError, TypeError):
        raise ValueError("invalid file size")

