def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string, not {0}".format(type(timestr).__name__))
    if default is not None and not isinstance(default, datetime):
        raise TypeError("default must be a datetime object, not {0}".format(type(default).__name__))
    if not isinstance(ignoretz, bool):
        raise TypeError("ignoretz must be a boolean")
    if tzinfos is not None and not isinstance(tzinfos, dict) and not callable(tzinfos):
        raise TypeError("tzinfos must be a dictionary or a function")

    if ignoretz and tzinfos is not None:
        raise ValueError("ignoretz and tzinfos cannot both be set")

    # If a default datetime is provided, use it instead of creating one
    if default is not None:
        default_tz = default.tzinfo
        default = default.replace(tzinfo=None)
    else:
        default_tz = None

    try:
        # Try parsing the datetime with the provided kwargs
        dt = _parse(timestr, default, ignoretz, tzinfos, **kwargs)
    except ParserError as e:
        # If the parse failed, try parsing again without the kwargs if they were specified
        if kwargs:
            dt = _parse(timestr, default, ignoretz, tzinfos)
        else:
            raise e

    if dt.tzinfo is None:
        # If the parsed datetime does not have a time zone, use the default if it was provided
        if default_tz is not None:
            dt = dt.replace(tzinfo=default_tz)
        # Otherwise, raise a ValueError
        else:
            raise ValueError("Cannot determine the time zone of the parsed date")

    return dt

