def verify_relayable_signature(public_key, doc, signature):
    # Verify the signature by checking the message in the signature and the signature in the message
    if public_key is None or doc is None or signature is None:
        raise ValueError("Public key and signature must both be specified")
    signature_elements = signature.signature_elements()
    for signature_element in signature_elements:
        element_verification_result = doc.verify_element(public_key, signature_element)
        if not element_verification_result:
            return False
    return True

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signature of an XML element to ensure that it was generated by a trusted source."""
    verify_result = public_key.verify(signature, doc, XMLDSIG_NS)
    if not verify_result:
        raise SignatureError("Signature verification failed")

