def validate_from_file(cls, yaml_file):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """

        # Open the YAML file and attempt to load it
        with open(yaml_file, 'r') as f:
            data = yaml.load(f, Loader=yaml.FullLoader)

        # Remove any None values and convert dictionaries to lists
        #data = {key: value for key, value in data.items() if value is not None}
        data = {key: [value] if isinstance(value, dict) else value for key, value in data.items() if value is not None}

        # Validate that all mandatory fields are present in the YAML file
        for key, value in cls.__mandatory_fields__.items():
            if key not in data:
                raise IRValidatorException(f"The file does not contain the mandatory field: {key}")

        # Validate that all fields that are not marked as optional are of the correct type
        for key, value in data.items():
            if key not in cls.__mandatory_fields__ and key not in cls.__optional_fields__:
                raise IRValidatorException(f"The field is not recognized: {key}")

            if key in cls.__mandatory_fields__ and isinstance(value, list):
                raise IRValidatorException(f"The field is a list and cannot be marked as mandatory: {key}")

            if key in cls.__optional_fields__ and not isinstance(value, list):
                raise IRValidatorException(f"The field is not a list and cannot be marked as optional: {key}")

            # Recurse into nested dictionaries
            if isinstance(value, dict):
                validate_from_file(cls, value)

